// Q1. One combined EMULATOR-ONLY change on Z5: the AF-ON builder reads the
// mirror. Half-press All is test setup via the settings setter. The mirror
// seed is test setup. K2 is Z5 with the same half-press setup and no seed.
// K1 is stock. Subject Detect is 0x1e71[0]. A failed assertion ends ok:false.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/exp_q1_t6.mjs om-emu
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/exp_q1_t6.mjs om-emu\n');
  process.exit(2);
}
let API_SET = 0;
async function bindApi() {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  API_SET = A(0x50ac4afe);
}
const GET = 0x60063380;
const SET = 0x60063431;
const CONVERTER = 0x604050e5;
const MIRROR = 0xa031eeb0;
const MIRROR_C = 0x6031eeb0;
const ZONE = 0xa031e920;
const POSE = 0xa32c568c;
const RET_ZONE = 0x60a8f71c;
const RET_SIZE = 0x60a8f757;
const RET_POS = 0x60a8f76e;
const RET_PLUS9 = 0x60a8f789;
const CALL_CONV = 0x60a8f71f;
const BACK_CONV = 0x60a8f726;
const ALL = [0x0e, 0x02, 0x02, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const SMALL = [0x11, 0x02, 0x03, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const STOCK = [0x0e, 0x02, 0x02, 0x00, 0x1b, 0x00, 0x27, 0x00, 0x00, 0x00];
const EDGES = [
  ['s1', 'down'], ['s1', 'up'],
  ['afon', 'down'], ['afon', 'up'],
  ['s1', 'down'], ['afon', 'down'], ['afon', 'up'], ['s1', 'up'],
  ['afon', 'down'], ['s1', 'down'], ['s1', 'up'], ['afon', 'up'],
];
const OWNERS = [1, 0, 2, 0, 1, 2, 1, 0, 2, 2, 2, 0];
const AFON_EDGES = new Set([2, 5, 8, 9, 10]);
const HALF_CELLS = {
  k99a1: [0, 0, 2, 0, 2, 0, 5, 5],
  k9a41: 0,
  k84d1: 2,
  k88b2: 526,
  k5962: [526, 526, 526, 526, 526, 526],
  k1dd1: [1, 1, 3, 3, 3, 3, 3, 3, 3, 3],
  k1df1: [1, 1, 1, 1, 0, 0, 0, 0],
  k1e01: 0,
  kdfa1: 0,
  k99d2: [526, 526, 526],
  k90a1: [1, 1],
  k1db1: 0,
  k1dc1: 0,
};
const OUT = resolve('work/out/edges-q1-t6.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ id: row.id, pass: row.pass, problems: row.problems, step: row.step }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

function readKey(ctx, key, index) {
  return ctx.l.call(ctx.native(GET), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
}
function setKey(ctx, key, index, value) {
  ctx.l.call(ctx.native(SET), { d0: key, d1: index, a1: value }, null, null, 200000);
  const back = readKey(ctx, key, index);
  if (back !== (value & 0xffff)) throw new Error('setter readback ' + key.toString(16) + ' ' + back);
  return back;
}
function setPublic(ctx, sid, value) {
  const grouped = sid === 289 || sid === 66 || sid === 67;
  const argument = grouped
    ? (ctx.l.call(ctx.native(CONVERTER), { d0: sid, d1: value }, null, null, 200000).d0 >>> 0)
    : value;
  ctx.l.call(API_SET, { d0: sid, d1: argument }, null, null, 200000);
  ctx.idle(400);
}
function half(ctx) {
  return {
    k99a1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x99a1, i)),
    k9a41: readKey(ctx, 0x9a41, 0),
    k84d1: readKey(ctx, 0x84d1, 0),
    k88b2: readKey(ctx, 0x88b2, 0),
    k5962: Array.from({ length: 6 }, (_, i) => readKey(ctx, 0x5962, i)),
    k1dd1: Array.from({ length: 10 }, (_, i) => readKey(ctx, 0x1dd1, i)),
    k1df1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x1df1, i)),
    k1e01: readKey(ctx, 0x1e01, 0),
    kdfa1: readKey(ctx, 0xdfa1, 0),
    k99d2: [0, 1, 2].map((i) => readKey(ctx, 0x99d2, i)),
    k90a1: [readKey(ctx, 0x90a1, 0), readKey(ctx, 0x90a1, 1)],
    k1db1: readKey(ctx, 0x1db1, 0),
    k1dc1: readKey(ctx, 0x1dc1, 0),
  };
}
function mirrorBytes(ctx) {
  return Array.from(ctx.l.sim.read(MIRROR, 55));
}
function q1Mirror() {
  const m = new Uint8Array(55);
  m[1] = 2;
  m[0x0c] = 529 & 0xff;
  m[0x0d] = (529 >> 8) & 0xff;
  m[0x22] = 529 & 0xff;
  m[0x23] = (529 >> 8) & 0xff;
  return Array.from(m);
}
function installProfileRead(ctx) {
  const link = { area: 0, pos: 0 };
  let inConv = false;
  const seen = [];
  const counts = { zone: 0, size: 0, pos: 0, plus9: 0, dim: 0 };
  const u8 = (a) => ctx.l.sim.read(a, 1)[0];
  const u16 = (a) => { const b = ctx.l.sim.read(a, 2); return b[0] | (b[1] << 8); };
  const bank = () => {
    if (!(link.area === 1 && link.pos === 1)) return 1;
    const pose = ctx.l.sim.u32(POSE) >>> 0;
    if (pose === 2) return 5;
    if (pose === 4) return 3;
    return 1;
  };
  const refresh = () => {
    link.area = readKey(ctx, 0x1db1, 0);
    link.pos = readKey(ctx, 0x1dc1, 0);
  };
  ctx.l.observe(ctx.native(CALL_CONV), () => { inConv = true; }, 'obs-builder-converter');
  ctx.l.observe(ctx.native(BACK_CONV), () => { inConv = false; }, 'obs-builder-converter-back');
  ctx.l.hook(ctx.native(GET), (h, r) => {
    const back = r.mdr >>> 0;
    const key = r.d0 & 0xffff;
    const index = r.d1 & 0xffff;
    if (seen.length < 12) seen.push({ back: '0x' + back.toString(16), key, index, inConv });
    const b = bank();
    if (back === RET_ZONE) {
      counts.zone += 1;
      let v = u8(MIRROR + b);
      if (v === 0xff) v = u8(ZONE);
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_SIZE) {
      counts.size += 1;
      let v = u8(MIRROR + 0x08);
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_POS) {
      counts.pos += 1;
      let v = u16(MIRROR + 0x0a + b * 2);
      if (v === 0xffff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    if (back === RET_PLUS9) {
      counts.plus9 += 1;
      h.finish(r, { d0: 0 });
      return;
    }
    if (inConv && key === 0x1dd1) {
      counts.dim += 1;
      let v = u8(MIRROR + 0x16 + (index & 0xff));
      if (v === 0xff) v = 0;
      h.finish(r, { d0: v });
      return;
    }
    ctx.l.passthrough(r);
  }, 'EMULATOR-ONLY profile read from the mirror. Role: behaviour.');
  return { refresh, counts, seen, link };
}

async function showSubject(ctx, id) {
  ctx.press('menu');
  for (let i = 0; i < 20; i++) ctx.press('left');
  const shot = ctx.shot('subject');
  const subject = readKey(ctx, 0x1e71, 0);
  const problems = [];
  if (shot.highlight !== 'Subject Detection') problems.push('highlight');
  if (!shot.texts.includes('Off')) problems.push('off-text');
  if (subject !== 0) problems.push('subject');
  emit({
    id, step: 'subject', pass: problems.length === 0, problems,
    highlight: shot.highlight, texts: shot.texts, subject, file: shot.file,
    note: '0x1e71[0] is MODE_SUBJECT_DETECT. 0x90a1 is not Subject Detect.',
  });
  if (problems.length) throw new Error(id + ' subject ' + problems.join(','));
  for (let i = 0; i < 8 && ctx.s.screen() !== 'shooting'; i++) ctx.press('menu');
  if (ctx.s.screen() !== 'shooting') throw new Error(id + ' did not return to shooting');
}

function pokeAll(ctx) {
  setKey(ctx, 0x84d1, 0, 2);
  setKey(ctx, 0x1dd1, 0, 1);
  setKey(ctx, 0x1dd1, 1, 1);
  setKey(ctx, 0x99a1, 0, 0);
}

function seed(ctx, bytes) {
  const buf = Buffer.from(bytes);
  ctx.l.sim.write(MIRROR, buf);
  ctx.l.sim.write(MIRROR_C, buf);
}

async function session(role) {
  const profile = role === 'candidate';
  const z5 = role !== 'k1';
  let hook = null;
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-q1-' + role + '-t6.jsonl',
    tag: 'q1-' + role + '-t6',
    candidate: z5,
    help: true,
    rowLabel: true,
    overlayCsv: profile
      ? 'work/out/overlay-changed-bytes.csv'
      : (z5 ? 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes-c1.csv' : null),
    fatalShots: true,
    explanation: profile
      ? 'Q1 candidate. Combined profile read. Mirror seed is test setup. Half-press All is test setup. EMULATOR-ONLY. Role: behaviour.'
      : (z5
        ? 'Q1 K2. Z5, same half-press All test setup, no mirror seed, no profile-read hook.'
        : 'Q1 K1. Stock image. No overlay, no poke, no mirror.'),
    change: profile ? 'combined: zone, size, position, custom dimensions, +9' : 'none',
    async drive(ctx) {
      await bindApi();
      if (profile) hook = installProfileRead(ctx);
      ctx.bringUp();
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(400);
      setPublic(ctx, 289, 0);
      if (ctx.s.get(289) !== 0 || ctx.s.get(25) !== 0) throw new Error(role + ' focus not S-AF');
      await showSubject(ctx, 'q1-' + role + '-subject');
      if (z5) pokeAll(ctx);
      const wantMirror = profile ? q1Mirror() : null;
      if (profile) {
        seed(ctx, wantMirror);
        hook.refresh();
      }
      const gotHalf = half(ctx);
      const gotMirror = mirrorBytes(ctx);
      const setupProblems = [];
      if (readKey(ctx, 0x1e71, 0) !== 0) setupProblems.push('subject');
      if (z5 && !same(gotHalf, HALF_CELLS)) setupProblems.push('half');
      if (profile && !same(gotMirror, wantMirror)) setupProblems.push('mirror');
      if (profile && !same(Array.from(ctx.l.sim.read(MIRROR_C, 55)), wantMirror)) setupProblems.push('mirror-cached');
      emit({
        id: 'q1-' + role + '-setup', step: 'setup', pass: setupProblems.length === 0,
        problems: setupProblems, half: gotHalf, mirror: gotMirror, zone: ctx.readByte(ZONE),
      });
      if (setupProblems.length) throw new Error(role + ' setup ' + setupProblems.join(','));
      for (let i = 0; i < EDGES.length; i++) {
        if (hook) hook.refresh();
        ctx.key(EDGES[i][0], EDGES[i][1]);
        ctx.idle(250);
        const shot = ctx.shot('e' + i);
        const own = ctx.readOwn();
        const target = ctx.readTarget();
        const nowHalf = half(ctx);
        const nowMirror = mirrorBytes(ctx);
        const problems = [];
        const wantTarget = !z5 ? STOCK : (profile && AFON_EDGES.has(i) ? SMALL : ALL);
        if (!same(target, wantTarget)) problems.push('target');
        if (z5 && own[6] !== 1) problems.push('enabled');
        if (z5 && own[5] !== 0) problems.push('status');
        if (z5 && own[4] !== OWNERS[i]) problems.push('owner');
        if (readKey(ctx, 0x1e71, 0) !== 0) problems.push('subject');
        if (z5 && !same(nowHalf, HALF_CELLS)) problems.push('half');
        if (profile && !same(nowMirror, wantMirror)) problems.push('mirror');
        if (!profile && z5 && nowMirror.some((b) => b !== 0xff)) problems.push('mirror-seeded');
        const id = 'q1-' + role + '-e' + i;
        emit({
          id, step: 'edge', pass: problems.length === 0, problems,
          key: EDGES[i][0], dir: EDGES[i][1],
          target, wantTarget, owner: own[4], status: own[5], enabled: own[6],
          half: nowHalf, mirror: nowMirror, subject: readKey(ctx, 0x1e71, 0),
          file: shot.file,
        });
        if (problems.length) throw new Error(id + ' ' + problems.join(','));
      }
      if (hook) emit({ id: 'q1-candidate-hook', step: 'hook', pass: true, counts: hook.counts, seen: hook.seen });
    },
  });
  emit({ id: 'q1-' + role + '-session', step: 'session', pass: result.ok, failed: result.failed });
  if (!result.ok) throw new Error(role + ' session failed');
}

try {
  emit({
    id: 'q1-plan', step: 'plan', pass: true,
    note: 'AF-ON Small at 529. Half-press All. K2 has the same half-press and no mirror. K1 is stock.',
    all: ALL, small: SMALL, stock: STOCK, half: HALF_CELLS, mirror: q1Mirror(),
  });
  await session('candidate');
  await session('k2');
  await session('k1');
  emit({ id: 'q1-done', step: 'done', pass: true, ok: true });
} catch (e) {
  emit({ id: 'q1-done', step: 'done', pass: false, ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exit(1);
}
